<?php $__pills = function (array $rows, string $key, array $first, string $total) { $c = tms_count_by($rows, $key); $o = [[$total, count($rows), 'dark']];
  $tone = ['Delivered' => 'good', 'Cancelled' => 'bad', 'Breakdown' => 'bad', 'Accident' => 'bad', 'In Transit' => 'warn'];
  foreach ($first as $k) if (!empty($c[$k])) { $o[] = [$k === 'Gate Pass Created' ? 'Gate pass' : $k, $c[$k], $tone[$k] ?? '']; unset($c[$k]); }
  foreach ($c as $k => $n) if ($k !== '') $o[] = [$k, $n, $tone[$k] ?? '']; return $o; };
$__open = 0; foreach ($trips as $__t) if (in_array($__t['status'] ?? '', ['Planned', 'Assigned', 'Loaded', 'Gate Pass Created'], true)) $__open += (int)($__t['total_boxes'] ?? 0);
echo tms_stats(array_merge($__pills($trips, 'status', ['Planned','Assigned','Loaded','Gate Pass Created','In Transit','Delivered','Breakdown','Accident','Cancelled'], 'trips'), [['PKT not yet dispatched', $__open, 'warn'], ['Dispatch desk', '→', '', 'DISPATCH.php']])); ?>
<?php if (!empty($overLimit)): ?>
<div class="alert alert-err" role="alert"><b><?= count($overLimit) ?> planned trip(s) are over the limit</b> of <?= (int)tms_trip_max_pkt() ?> PKT / <?= (int)tms_trip_max_stores() ?> stores (made before this rule). Open each trip and use “Edit / Add / Remove Store” to fix it before dispatch:
<?= implode(', ', array_map(fn($t) => '<a href="PLANNING.php?tab=trips&amp;view=' . (int)$t['id'] . '">' . e($t['trip_code']) . '</a> (' . (int)$t['stops'] . ' stores, ' . (int)$t['pkt'] . ' PKT)', array_slice($overLimit, 0, 12))) ?><?= count($overLimit) > 12 ? ' …' : '' ?></div>
<?php endif; ?>
