Created'): ?><form method="post"><input type="hidden" name="action" value="dispatch_gatepass"><input type="hidden" name="trip_id" value="<?=$t['id']?>"><button type="submit">Dispatch</button></form><a href="PLANNING.php?tab=gatepasses&trip_id=<?=$t['id']?>">Open Gate Pass</a><?php endif; ?><button type="button" onclick='editTrip(<?=json_encode($t,JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_AMP)?>);closeRowMenus()'>Edit / Add / Remove Store</button><a href="PLANNING.php?tab=trips&view=<?=$t['id']?>">Open Trip</a><?php if(in_array($t['status'],['Planned','Assigned','Loaded'],true)): ?><form method="post"><input type="hidden" name="action" value="delete_trip"><input type="hidden" name="trip_id" value="<?=$t['id']?>"><button type="submit" class="danger-text" onclick="return confirm('Trip cancel/delete karein? Iske indents Planned me wapas aa jayenge aur vehicle/driver free ho jayenge.')">Cancel Trip</button></form><?php endif; ?></div></div></td></tr><?php endforeach;?></table></div></div>
